 +'<div class="pn-sites"><section class="ic-paper pn-site-selector"><div class="ic-section-head"><h2>Research institutions</h2><span>'+list.length+' loaded</span></div>'+p.items.map(r=>'<button class="pn-site-choice '+(inst?.id===r.id?'is-active':'')+'" data-action="select-institution:'+esc(r.id)+'"><span class="pn-site-symbol">'+icon('institutions')+'</span><span><strong>'+esc(r.data.name)+'</strong><small>'+esc([r.data.city,r.data.country].filter(Boolean).join(', '))+'</small></span></button>').join('')+(p.total?'':'<div class="ic-empty">Add an institution to begin mapping sites.</div>')+paging('siteList',p)+'</section>'
 +'<section class="pn-site-map">'+(inst?'<div class="pn-site-detail"><div class="pn-small-label">SITE CONNECTIONS</div><h2>'+esc(inst.data.name)+'</h2><p>'+esc([inst.data.city,inst.data.country,inst.data.kind].filter(Boolean).join(' · '))+'</p><p>'+esc(inst.data.capabilities||'Capabilities have not been documented')+'</p><div class="pn-site-counts"><div><b>'+aff.length+'</b><span>PI affiliations</span></div><div><b>'+exp.length+'</b><span>Public trial links</span></div></div></div><div class="pn-link-network">'+aff.map(a=>'<div class="pn-network-edge">'+rc(label('people',a.data.personId))+'<div><b>'+esc(label('people',a.data.personId))+'</b><span>'+esc(a.data.role||'Professional role')+' · '+esc(dateView(a.data.startAt))+'</span></div>'+button('View','select-person:'+esc(a.data.personId),'ic-text')+'</div>').join('')+(aff.length?'':'<div class="ic-empty">No confirmed investigator links yet.</div>')+'</div><div class="pn-site-actions">'+button('Add affiliation','new:affiliations','ic-primary',!editable)+button('Edit site','edit:institutions:'+inst.id,'ic-outline',!editable)+button('Archive site','archive:institutions:'+inst.id,'ic-danger',!editable)+'</div>':'<div class="ic-empty">No institution selected.</div>')+'</section></div>'
